Create a label-extraction function
Add:
extract_variable_label &lt;- function(
    variable) {

  variable_label &lt;- attr(
    variable,
    "label"
  )

  if (
    is.null(
      variable_label
    ) ||
      length(
        variable_label
      ) == 0
  ) {
    NA_character_
  } else {
    as.character(
      variable_label[[1]]
    )
  }
}

