Create a safe descriptive-summary function
Add:
summarize_hemoglobin &lt;- function(
    data) {

  nonmissing_values &lt;- data$LBXHGB[
    !is.na(
      data$LBXHGB
    )
  ]

  if (
    length(
      nonmissing_values
    ) == 0
  ) {
    return(
      tibble::tibble(
        records = nrow(
          data
        ),
        nonmissing_hemoglobin = 0L,
        mean_hemoglobin = NA_real_,
        standard_deviation = NA_real_,
        standard_error = NA_real_,
        minimum = NA_real_,
        first_quartile = NA_real_,
        median_hemoglobin = NA_real_,
        third_quartile = NA_real_,
        maximum = NA_real_
      )
    )
  }

  records &lt;- length(
    nonmissing_values
  )

  standard_deviation &lt;- if (
    records &gt; 1
  ) {
    stats::sd(
      nonmissing_values
    )
  } else {
    NA_real_
  }

  standard_error &lt;- if (
    records &gt; 1
  ) {
    standard_deviation /
      sqrt(
        records
      )
  } else {
    NA_real_
  }

  tibble::tibble(
    records = nrow(
      data
    ),
    nonmissing_hemoglobin =
      records,
    mean_hemoglobin =
      mean(
        nonmissing_values
      ),
    standard_deviation =
      standard_deviation,
    standard_error =
      standard_error,
    minimum =
      min(
        nonmissing_values
      ),
    first_quartile =
      stats::quantile(
        nonmissing_values,
        probabilities = 0.25,
        names = FALSE
      ),
    median_hemoglobin =
      stats::median(
        nonmissing_values
      ),
    third_quartile =
      stats::quantile(
        nonmissing_values,
        probabilities = 0.75,
        names = FALSE
      ),
    maximum =
      max(
        nonmissing_values
      )
  )
}

